const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toLocaleString('th-TH',{maximumFractionDigits:3}),money=n=>Number(n).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});
let data,visible=[],purchased={};const storageKey='ohm-boq-purchases-v1';try{purchased=JSON.parse(localStorage.getItem(storageKey)||'{}');if(!purchased||typeof purchased!=='object')purchased={}}catch{}
const key=i=>`${i.sourceCell}|${i.name}`,done=i=>!!purchased[key(i)],priced=i=>typeof i.unitPrice==='number'&&i.unitPrice>0,quantified=i=>typeof i.quantity==='number'&&i.quantity>0;
function render(){const term=$('#search').value.toLocaleLowerCase('th-TH').trim(),category=$('#category').value,status=$('#status').value;visible=data.items.filter(i=>(!category||i.category===category)&&(!term||`${i.name} ${i.category} ${i.note} ${i.unit}`.toLocaleLowerCase('th-TH').includes(term))&&(status==='all'||status==='bought'&&done(i)||status==='pending'&&!done(i)||status==='unpriced'&&!priced(i)||status==='unquantified'&&!quantified(i)));
 $('#summary').innerHTML=`<div class="stat"><span>รายการใน BOQ</span><b>${data.items.length}</b><small>${new Set(data.items.map(i=>i.category)).size} หมวด</small></div><div class="stat"><span>ติ๊กซื้อแล้ว</span><b>${data.items.filter(done).length} / ${data.items.length}</b><small>ติดตามเป็นรายรายการ</small></div><div class="stat"><span>ค่าวัสดุที่ใส่ราคาไว้</span><b>฿${money(data.materialTotal)}</b><small>${data.items.filter(i=>!priced(i)).length} รายการยังไม่ระบุราคา</small></div><div class="stat"><span>รวมตาม Excel</span><b>฿${money(data.total)}</b><small>รวมขนส่งและ VAT ตามที่กรอกในไฟล์</small></div>`;
 $('#result').textContent=`แสดง ${visible.length} รายการ · รวมเฉพาะรายการที่แสดง ฿${money(visible.reduce((a,i)=>a+(Number(i.amount)||0),0))}`;$('#empty').hidden=!!visible.length;
 $('#items').innerHTML=visible.map(i=>`<tr class="${done(i)?'done':''}"><td><input type="checkbox" data-id="${i.id}" aria-label="ซื้อแล้ว: ${esc(i.name)}" ${done(i)?'checked':''}></td><td><div class="category">${esc(i.category==='Sheet1'?'งานอื่น (Sheet1)':i.category)}</div><b>${esc(i.name)}</b>${i.note?`<small>${esc(i.note)}</small>`:''}<small>อ้างอิง ${esc(i.sourceCell)}</small></td><td>${quantified(i)?`${fmt(i.quantity)} ${esc(i.unit||'')}`:`<span class="tag">${i.quantity===0?'0 ตาม BOQ':'รอยืนยันจำนวน'}</span>`}</td><td>${priced(i)?money(i.unitPrice):'<span class="tag">ยังไม่ระบุ</span>'}</td><td>${priced(i)&&quantified(i)?money(i.amount):'—'}</td><td class="shopping"><a href="https://shopee.co.th/search?keyword=${encodeURIComponent(i.name)}" target="_blank" rel="noopener noreferrer">ค้นหา Shopee ↗</a><small>ลิงก์ค้นหา ยังไม่ได้เลือกรุ่น</small></td></tr>`).join('');
 for(const input of document.querySelectorAll('[data-id]'))input.onchange=()=>{const item=data.items.find(i=>i.id===input.dataset.id);purchased[key(item)]=input.checked;try{localStorage.setItem(storageKey,JSON.stringify(purchased))}catch{$('#result').textContent='เบราว์เซอร์ไม่อนุญาตให้บันทึกสถานะ'}render()};
}
$('#print').onclick=()=>window.print();$('#csv').onclick=()=>{const rows=[['หมวด','รายการ','จำนวนตาม BOQ','หน่วย','ราคาต่อหน่วย','รวมตาม BOQ','หมายเหตุ','ซื้อแล้ว','อ้างอิง'],...visible.map(i=>[i.category,i.name,i.quantity,i.unit,i.unitPrice,i.amount,i.note,done(i)?'ซื้อแล้ว':'ยังไม่ซื้อ',i.sourceCell])],cell=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'},blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='OHM-BOQ-v413.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
try{const response=await fetch('./boq/items.json');if(!response.ok)throw Error('อ่าน BOQ ไม่ได้');data=await response.json();$('#source').textContent=`จาก ${data.sourceFile} · ไฟล์ปรับปรุง ${new Date(data.sourceModifiedAt).toLocaleString('th-TH',{dateStyle:'medium',timeStyle:'short'})}`;$('#category').innerHTML+=[...new Set(data.items.map(i=>i.category))].map(c=>`<option value="${esc(c)}">${esc(c==='Sheet1'?'งานอื่น (Sheet1)':c)}</option>`).join('');$('#extras').textContent=`ขนส่ง/เบ็ดเตล็ด ${fmt(data.shippingRate*100)}% = ฿${money(data.shipping)} · VAT ${fmt(data.vatRate*100)}% = ฿${money(data.vat)} · ใช้อัตราตามไฟล์ต้นฉบับ`;for(const id of ['search','category','status'])$('#'+id).addEventListener(id==='search'?'input':'change',render);render();window.boqQA={data,visible:()=>visible,purchased:()=>purchased}}catch(e){$('#source').textContent='โหลด BOQ ไม่สำเร็จ กรุณารีเฟรชหรือดาวน์โหลด Excel';console.error(e)}
